#include <iostream>
#include <regex>
#include <string>

// Function to convert Markdown to HTML
std::string markdownToHtml(const std::string& markdownText) {
    // Regular expression to convert Markdown to HTML
    std::regex regex(R"(```(.*?)```)");

    // Replace the Markdown text with HTML tags
    std::string htmlText;
    return std::regex_replace(markdownText, htmlText, regex, " <p>(```$1</p>)");
}

int main() {
    std::string markdownText = "```This is a markdown text```";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

This function uses a regular expression to find the Markdown blocks (```(.*?)```) and replaces them with the corresponding HTML tags (`<p>`). The `main` function demonstrates how to use the `markdownToHtml` function and prints both the Markdown and HTML texts.

